31	    /**
32	     * Bootstrap any application services.
33	     */
34	    public function boot(): void
35	    {
36	        $this->defineCatalogHierarchy();
37	
38	        // Morph map enforced: alias polimorfici stabili e leggibili. Serve
39	        // all'AssetManager del core, che porta il record proprietario nell'URL
40	        // via morph alias (es. /admin/assets/product/5 invece del FQCN con
41	        // backslash). enforceMorphMap impone che OGNI modello che compare in
42	        // una colonna polimorfica (media.model_type, asset_folders.folderable_type,
43	        // e in futuro activitylog subject/causer) abbia un alias qui, altrimenti
44	        // lancia: per questo sono mappati tutti i modelli di dominio.
45	        Relation::enforceMorphMap([
46	            'product' => Product::class,
47	            'product_type' => ProductType::class,
48	            'category_1' => Category1::class,
49	            'category_2' => Category2::class,
50	            'designer' => Designer::class,
51	            'material' => Material::class,
52	            'user' => User::class,
53	        ]);
