<?php

declare(strict_types=1);

namespace AtrioTeam\DigitalHub\Filament;

use AtrioTeam\DigitalHub\Assets\Filament\Pages\AssetManager;
use AtrioTeam\DigitalHub\Catalog\Filament\Pages\Catalog;
use AtrioTeam\DigitalHub\Pim\Filament\Tables\DigitalHubTableMacro;
use Filament\Contracts\Plugin;
use Filament\MinimalTheme;
use Filament\Notifications\Livewire\Notifications;
use Filament\Panel;
use Filament\Support\Enums\Alignment;
use Filament\Tables\Table;

/**
 * A simple Filament plugin to configure the panel via this package.
 */
class DigitalHubPlugin implements Plugin
{
    public static function make(): static
    {
        /** @var static $plugin */
        $plugin = app(static::class);

        return $plugin;
    }

    public function getId(): string
    {
        return 'digital-hub';
    }

    public function register(Panel $panel): void
    {
        $panel
            ->plugin(MinimalTheme::make())
            ->viteTheme('vendor/atrioteam/digital-hub/resources/theme/digital-hub-theme.css')
            ->font('Open Sans')
            ->pages([
                Catalog::class,
                AssetManager::class,
            ]);

        $primaryColor = config('digital-hub.primary_color');
        if (is_string($primaryColor) && $primaryColor !== '') {
            /** @var array<int, string> $color */
            $color = \Filament\Support\Colors\Color::{$primaryColor};
            $panel
            ->colors([
                'primary' => $color,
            ]);
        }

    }

    public function boot(Panel $panel): void
    {
        Notifications::alignment(Alignment::Center);

        Table::configureUsing(function (Table $table): Table {
            return $table->defaultPaginationPageOption(50);
        });

        DigitalHubTableMacro::register();


    }

}
